"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionStyle,
  type MotionValue,
  type SpringOptions,
} from "motion/react";
import { type ReactNode, useRef } from "react";

import { cn } from "@/lib/utils";

/** One app in the dock. The label names the icon and shows above it on hover or focus. */
export interface MagnifyDockItem {
  id: string;
  label: string;
  icon: ReactNode;
  /** Shows a dot under the icon, for an app that is open. */
  open?: boolean;
  onSelect?: () => void;
}

/** Props for a magnifying dock. */
export interface MagnifyDockProps {
  /** Names the dock for screen readers, for example "Apps". */
  label: string;
  items: MagnifyDockItem[];
  className?: string;
}

// Sizes in rem. An icon at rest is a 2.75rem touch target and grows to 4rem under the pointer.
const REST = 2.75;
const PEAK = 4;
// Icons within this many rem of the pointer grow, the nearest the most.
const REACH = 9;
// Damping 34 is just over 2 × √280: critically damped, so a grown icon settles without wobble.
const GROW: SpringOptions = { stiffness: 280, damping: 34, mass: 1 };
const AWAY = Number.POSITIVE_INFINITY;

const rootFontSize = () => Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;

function DockButton({ item, pointerX }: { item: MagnifyDockItem; pointerX: MotionValue<number> }) {
  const ref = useRef<HTMLButtonElement>(null);
  // Distance in rem from the pointer to this icon's centre.
  const distance = useTransform(pointerX, (x) => {
    const box = ref.current?.getBoundingClientRect();
    if (!box || !Number.isFinite(x)) return AWAY;
    return (x - (box.left + box.width / 2)) / rootFontSize();
  });
  const target = useTransform(distance, [-REACH, 0, REACH], [REST, PEAK, REST], { clamp: true });
  const size = useSpring(target, GROW);
  const width = useTransform(size, (value) => `${value}rem`);

  return (
    <motion.button
      ref={ref}
      type="button"
      aria-label={item.label}
      onClick={item.onSelect}
      // The size reaches the classes through a custom property, so the spring drives it without a render.
      // SAFETY: motion writes a motion value into a CSS custom property; MotionStyle only lacks custom keys in its type.
      style={{ "--tile": width } as MotionStyle}
      className={cn(
        "group relative grid size-(--tile) shrink-0 cursor-pointer touch-manipulation place-items-center rounded-xl bg-muted text-foreground outline-none",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
      )}
    >
      {/* The icon scales with its tile, so it stays sharp at every size. Give it size-full. */}
      <span aria-hidden="true" className="grid size-1/2 place-items-center">
        {item.icon}
      </span>
      {/* The tip repeats the accessible name for sighted users, so it stays hidden from screen readers. */}
      <span
        aria-hidden="true"
        className="pointer-events-none invisible absolute bottom-full left-1/2 mb-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background opacity-0 group-hover:visible group-hover:opacity-100 group-focus-visible:visible group-focus-visible:opacity-100 motion-safe:transition-opacity"
      >
        {item.label}
      </span>
      {item.open ? (
        <span aria-hidden="true" className="absolute -bottom-1.5 left-1/2 size-1 -translate-x-1/2 rounded-full bg-foreground" />
      ) : null}
    </motion.button>
  );
}

/**
 * A row of app icons that grow as the pointer passes over them, the nearest
 * the most, so the one you aim at is the biggest. A keyboard user gets the
 * same growth on the focused icon. Touch and reduced motion keep every icon
 * at its resting size.
 */
export function MagnifyDock({ label, items, className }: MagnifyDockProps) {
  const pointerX = useMotionValue(AWAY);
  const reduceMotion = useReducedMotion();

  const aim = (x: number) => {
    if (!reduceMotion) pointerX.set(x);
  };

  return (
    <div
      role="group"
      aria-label={label}
      onPointerMove={(event) => {
        if (event.pointerType === "mouse") aim(event.clientX);
      }}
      onPointerLeave={() => pointerX.set(AWAY)}
      onFocus={(event) => {
        // Only keyboard focus aims the growth; a click already has the pointer there.
        if (!event.target.matches(":focus-visible")) return;
        const box = event.target.getBoundingClientRect();
        aim(box.left + box.width / 2);
      }}
      onBlur={() => pointerX.set(AWAY)}
      className={cn(
        // Items sit on the bottom edge, so a growing icon rises out of the dock rather than pushing it down.
        "inline-flex items-end gap-2 rounded-3xl border border-border bg-card p-3 shadow-sm",
        className,
      )}
    >
      {items.map((item) => (
        <DockButton key={item.id} item={item} pointerX={pointerX} />
      ))}
    </div>
  );
}
